<div class="page-title">Review Queue</div><p class="page-subtitle">Trade and Pre/Post Review work that is currently pending or completed.</p>
<div class="card"><div class="actions"><?php foreach(['all'=>'All','trade'=>'Trade','day'=>'Day','week'=>'Week','month'=>'Month','year'=>'Year'] as $key=>$label):?><a class="secondary-link <?=$filter===$key?'active-filter':''?>" href="/review-queue?filter=<?=$key?>"><?=e($label)?></a><?php endforeach;?></div></div>
<div class="card table-wrap"><table><thead><tr><th>Type</th><th>Period / Trade</th><th>Date</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><span class="badge"><?=e(ucfirst($r['kind']))?></span></td><td><?=e($r['label'].' · '.$r['period'])?></td><td><?=e($r['date']??'—')?></td><td><?=e($r['due']??'—')?></td><td><?=e(ucfirst(str_replace('_',' ',$r['status'])))?></td><td><a href="<?=e($r['url'])?>">Review</a></td></tr><?php endforeach;if(!$reviews):?><tr><td colspan="6" class="muted">No reviews in the queue.</td></tr><?php endif;?></tbody></table></div>
